/**
 * FILE: concept_5_cashflow_power_battery.js
 * THEME: Finance & Investment — Cashflow Power Battery & Passive Income Charger
 * STYLE: Modern Flat Vector with Solid Chroma Green Screen (#00FF00)
 * ASPECT RATIO: 16:9 | RESOLUTION READY: FHD / 2K / 4K (Ultra HD)
 * DURATION: 20 Seconds Seamless Loop | SCENES: 1
 * TARGET EXPORT BITRATE: 100 Mbps (Uncompressed Crisp Vector Edges, Zero Glow/Bloom)
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const s = minSide / 1080;
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Harmonic phase multiples for 100% seamless 20-second loop
  const tau = Math.PI * 2;
  const p1 = sceneProgress * tau + currentScene * 0;
  const p2 = sceneProgress * tau * 2;
  const p3 = sceneProgress * tau * 3;
  const p4 = sceneProgress * tau * 4;

  // Synchronized battery charge level (cycles smoothly between 35% and 92%)
  const chargeNorm = 0.635 - 0.285 * Math.cos(p1) + 0.04 * Math.sin(p3);

  // Color Palette (Crisp Commercial Flat Vector, Zero Glow)
  const COL = {
    greenScreen: '#00FF00',
    outline: '#162035',
    surfaceWhite: '#FFFFFF',
    surfaceLight: '#F1F5F9',
    surfaceMuted: '#CBD5E1',
    slateDark: '#334155',
    slateMid: '#64748B',
    batteryShell: '#1E293B',
    batteryBorder: '#475569',
    amberLight: '#FEF08A',
    amberMid: '#FACC15',
    amberDark: '#EAB308',
    amberDeep: '#CA8A04',
    emeraldLight: '#A7F3D0',
    emeraldMid: '#22C55E',
    emeraldDark: '#15803D',
    electricCyan: '#38BDF8',
    electricBlue: '#0284C7',
    cableDark: '#0F172A'
  };

  const strokeW = 5.5 * s;
  const thinStrokeW = 3.5 * s;

  ctx.save();
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // 1. SOLID GREEN SCREEN BACKGROUND
  ctx.fillStyle = COL.greenScreen;
  ctx.fillRect(0, 0, width, height);

  // Helper: Rounded Rectangle Path
  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function fillAndStroke(fillColor, outlineColor, lineWidth) {
    if (fillColor) {
      ctx.fillStyle = fillColor;
      ctx.fill();
    }
    if (outlineColor && lineWidth > 0) {
      ctx.strokeStyle = outlineColor;
      ctx.lineWidth = lineWidth;
      ctx.stroke();
    }
  }

  // Helper: Crisp Vector Dollar Emblem
  function drawVectorDollar(centerX, centerY, scaleSize, color, lineW) {
    const w = 13 * scaleSize;
    const h = 20 * scaleSize;
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.beginPath();
    ctx.moveTo(centerX + w * 0.75, centerY - h * 0.45);
    ctx.bezierCurveTo(
      centerX + w * 0.75, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.35
    );
    ctx.bezierCurveTo(
      centerX - w * 0.85, centerY + h * 0.02,
      centerX + w * 0.85, centerY - h * 0.02,
      centerX + w * 0.85, centerY + h * 0.40
    );
    ctx.bezierCurveTo(
      centerX + w * 0.85, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.45
    );
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(centerX, centerY - h * 0.98);
    ctx.lineTo(centerX, centerY + h * 0.98);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Vector Upward Arrow
  function drawUpArrow(centerX, centerY, size, color, lineW) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.beginPath();
    ctx.moveTo(centerX, centerY + size * 0.7);
    ctx.lineTo(centerX, centerY - size * 0.65);
    ctx.moveTo(centerX - size * 0.55, centerY - size * 0.1);
    ctx.lineTo(centerX, centerY - size * 0.7);
    ctx.lineTo(centerX + size * 0.55, centerY - size * 0.1);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Gold Coin Medallion
  function drawGoldMedallion(centerX, centerY, radius, dollarScale) {
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, 0, tau);
    fillAndStroke(COL.amberMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.arc(centerX, centerY, radius * 0.74, 0, tau);
    fillAndStroke(COL.amberLight, COL.outline, 2.5 * s);

    drawVectorDollar(centerX, centerY, dollarScale, COL.outline, 3.2 * s);
  }

  // Helper: Side-View Stacked Coin Cylinder
  function drawCoinCylinder(centerX, topY, coinW, coinH) {
    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(COL.amberMid, COL.outline, thinStrokeW);

    roundedRectPath(centerX - coinW * 0.40, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.amberLight, null, 0);

    roundedRectPath(centerX + coinW * 0.20, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.amberDeep, null, 0);

    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(null, COL.outline, thinStrokeW);
  }

  // =========================================================================
  // 2. STRUCTURAL BASELINE PLATFORM & NON-INTERSECTING ENERGY BRIDGES
  // =========================================================================
  const baseLineY = cy + 395 * s;

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = strokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 735 * s, baseLineY);
  ctx.lineTo(cx + 735 * s, baseLineY);
  ctx.stroke();

  // Outer baseline accent ticks
  const tickShift = Math.sin(p2) * 6 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 810 * s - tickShift, baseLineY);
  ctx.lineTo(cx - 760 * s - tickShift, baseLineY);
  ctx.moveTo(cx + 760 * s + tickShift, baseLineY);
  ctx.lineTo(cx + 810 * s + tickShift, baseLineY);
  ctx.stroke();

  // Sub-platform line
  ctx.beginPath();
  ctx.moveTo(cx - 360 * s, baseLineY + 18 * s);
  ctx.lineTo(cx + 360 * s, baseLineY + 18 * s);
  ctx.stroke();

  // Dedicated Horizontal Energy Flow Cables in Lower Corridor (y = cy + 205*s)
  // Left gap: [cx - 245*s, cx - 175*s] | Right gap: [cx + 175*s, cx + 245*s]
  const bridgeY = cy + 205 * s;
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = thinStrokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 245 * s, bridgeY);
  ctx.lineTo(cx - 175 * s, bridgeY);
  ctx.moveTo(cx + 175 * s, bridgeY);
  ctx.lineTo(cx + 245 * s, bridgeY);
  ctx.stroke();

  // Traveling electrical energy pulses on cables
  const eProgL = (sceneProgress * 4) % 1;
  ctx.beginPath();
  ctx.arc(cx - 238 * s + eProgL * 56 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.electricCyan, COL.outline, 2.5 * s);

  const eProgR = (sceneProgress * 4 + 0.5) % 1;
  ctx.beginPath();
  ctx.arc(cx + 182 * s + eProgR * 56 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.amberMid, COL.outline, 2.5 * s);

  // =========================================================================
  // 3. LEFT-TOP ZONE: CASHFLOW EFFICIENCY & POWER TELEMETRY CARD
  // Bounding Box: x in [cx - 685*s, cx - 255*s], y in [cy - 360*s, cy - 35*s]
  // =========================================================================
  const ltFloatY = Math.sin(p2) * 4.5 * s;
  const ltX = cx - 685 * s;
  const ltY = cy - 360 * s + ltFloatY;
  const ltW = 430 * s;
  const ltH = 315 * s;

  roundedRectPath(ltX, ltY, ltW, ltH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Top Header Strip inside Left-Top Card
  roundedRectPath(ltX + 18 * s, ltY + 18 * s, ltW - 36 * s, 46 * s, 12 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  // Green Energy Badge on Left of Header
  roundedRectPath(ltX + 26 * s, ltY + 25 * s, 96 * s, 32 * s, 8 * s);
  fillAndStroke(COL.emeraldMid, COL.outline, 2.8 * s);
  drawUpArrow(ltX + 48 * s, ltY + 41 * s, 16 * s, COL.outline, 3.5 * s);
  roundedRectPath(ltX + 68 * s, ltY + 36 * s, 42 * s, 10 * s, 5 * s);
  fillAndStroke(COL.surfaceWhite, null, 0);

  // Header Title Bar & Status Dot
  roundedRectPath(ltX + 140 * s, ltY + 35 * s, 185 * s, 12 * s, 6 * s);
  fillAndStroke(COL.slateDark, null, 0);
  ctx.beginPath();
  ctx.arc(ltX + ltW - 42 * s, ltY + 41 * s, 9 * s, 0, tau);
  fillAndStroke(COL.amberMid, COL.outline, 2.5 * s);

  // Inner Power Chart Frame (y: ltY + 80*s, height: 215*s)
  const cFrameX = ltX + 18 * s;
  const cFrameY = ltY + 80 * s;
  const cFrameW = ltW - 36 * s;
  const cFrameH = 215 * s;

  roundedRectPath(cFrameX, cFrameY, cFrameW, cFrameH, 14 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  // Horizontal Grid Lines
  ctx.strokeStyle = COL.surfaceMuted;
  ctx.lineWidth = 2 * s;
  for (let g = 1; g <= 3; g++) {
    const gy = cFrameY + (cFrameH / 4) * g;
    ctx.beginPath();
    ctx.moveTo(cFrameX + 16 * s, gy);
    ctx.lineTo(cFrameX + cFrameW - 16 * s, gy);
    ctx.stroke();
  }

  // 5 Ascending Power Bars + Separated Trend Line & Nodes
  const barCount = 5;
  const barW = 36 * s;
  const barSpacing = (cFrameW - 76 * s) / (barCount - 1);
  const barBottomY = cFrameY + cFrameH - 14 * s;
  const basePowerRatios = [0.28, 0.36, 0.48, 0.62, 0.75];
  const nodePts = [];

  for (let i = 0; i < barCount; i++) {
    const bCenterX = cFrameX + 38 * s + i * barSpacing;
    const mod = 0.05 * Math.sin(p2 - i * 0.8);
    const bh = (basePowerRatios[i] + mod) * (cFrameH - 42 * s);
    const by = barBottomY - bh;

    const barCol = i === 4 ? COL.amberMid : (i >= 2 ? COL.emeraldMid : COL.electricCyan);
    roundedRectPath(bCenterX - barW * 0.5, by, barW, bh, 7 * s);
    fillAndStroke(barCol, COL.outline, thinStrokeW);

    nodePts.push({ x: bCenterX, y: by - 24 * s });
  }

  // Draw Trend Line
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 4 * s;
  ctx.beginPath();
  for (let i = 0; i < nodePts.length; i++) {
    if (i === 0) ctx.moveTo(nodePts[i].x, nodePts[i].y);
    else ctx.lineTo(nodePts[i].x, nodePts[i].y);
  }
  ctx.stroke();

  for (let i = 0; i < nodePts.length; i++) {
    ctx.beginPath();
    ctx.arc(nodePts[i].x, nodePts[i].y, 7 * s, 0, tau);
    fillAndStroke(i === 4 ? COL.amberMid : COL.surfaceWhite, COL.outline, 2.8 * s);
  }

  // =========================================================================
  // 4. LEFT-BOTTOM ZONE: AUTOMATED SAVINGS PANEL & GOLD RESERVES PEDESTAL
  // Bounding Box: x in [cx - 685*s, cx - 255*s], y in [cy + 25*s, cy + 395*s]
  // =========================================================================
  const lbFloatY = Math.cos(p2) * 4 * s;
  const lbX = cx - 685 * s;
  const lbY = cy + 25 * s + lbFloatY;
  const lbW = 430 * s;
  const lbCardH = 190 * s;

  // 4A. Upper Automated Cashflow Allocation Card
  roundedRectPath(lbX, lbY, lbW, lbCardH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Left Segmented Donut Ring inside Card
  const dCX = lbX + 82 * s;
  const dCY = lbY + lbCardH * 0.5;
  const dR = 54 * s;
  const dAngles = [0, tau * 0.42, tau * 0.76, tau];
  const dCols = [COL.emeraldMid, COL.electricCyan, COL.amberMid];

  for (let k = 0; k < 3; k++) {
    ctx.beginPath();
    ctx.moveTo(dCX, dCY);
    ctx.arc(dCX, dCY, dR, p1 + dAngles[k], p1 + dAngles[k + 1]);
    ctx.closePath();
    fillAndStroke(dCols[k], COL.outline, thinStrokeW);
  }
  ctx.beginPath();
  ctx.arc(dCX, dCY, 25 * s, 0, tau);
  fillAndStroke(COL.surfaceWhite, COL.outline, thinStrokeW);

  // Right 3 Progress Meters
  const mStartX = lbX + 162 * s;
  const mWidth = 238 * s;
  for (let m = 0; m < 3; m++) {
    const my = lbY + 34 * s + m * 48 * s;
    roundedRectPath(mStartX, my, 88 * s, 9 * s, 4.5 * s);
    fillAndStroke(COL.slateMid, null, 0);

    roundedRectPath(mStartX, my + 15 * s, mWidth, 18 * s, 9 * s);
    fillAndStroke(COL.surfaceLight, COL.outline, 2.5 * s);

    const mFill = (0.55 + 0.28 * Math.sin(p2 + m * 1.2)) * (mWidth - 6 * s);
    roundedRectPath(mStartX + 3 * s, my + 18 * s, mFill, 12 * s, 6 * s);
    fillAndStroke(dCols[m], null, 0);
  }

  // 4B. Lower Gold Bullion & Coin Reserves on Pedestal (Sitting on baseLineY)
  const pedLX = lbX;
  const pedLW = lbW;
  const pedLH = 24 * s;
  const pedLY = baseLineY - pedLH;

  roundedRectPath(pedLX, pedLY, pedLW, pedLH, 8 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  function drawBullionBar(centerX, bottomY, barW, barH) {
    const topW = barW * 0.78;
    ctx.beginPath();
    ctx.moveTo(centerX - barW * 0.5, bottomY);
    ctx.lineTo(centerX - topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + barW * 0.5, bottomY);
    ctx.closePath();
    fillAndStroke(COL.amberMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.moveTo(centerX - topW * 0.38, bottomY - barH + 7 * s);
    ctx.lineTo(centerX + topW * 0.38, bottomY - barH + 7 * s);
    ctx.lineTo(centerX + topW * 0.42, bottomY - 7 * s);
    ctx.lineTo(centerX - topW * 0.42, bottomY - 7 * s);
    ctx.closePath();
    fillAndStroke(COL.amberLight, null, 0);
  }

  // Column 1 (Left): 2 Stacked Gold Bullion Bars (x center = lbX + 92*s, spans [22, 162])
  const bulCX = lbX + 92 * s;
  drawBullionBar(bulCX, pedLY, 140 * s, 38 * s);
  drawBullionBar(bulCX, pedLY - 38 * s, 122 * s, 36 * s);

  // Column 2 (Middle): 4 Stacked Gold Coins (x center = lbX + 242*s, spans [194, 290], 32*s clear gap!)
  const stackLCX = lbX + 242 * s;
  const cH = 24 * s;
  for (let c = 0; c < 4; c++) {
    drawCoinCylinder(stackLCX, pedLY - (c + 1) * cH, 96 * s, cH);
  }

  // Column 3 (Right): Front Gold Dollar Medallion on Stand (x center = lbX + 364*s, radius = 44*s -> spans [320, 408], 30*s clear gap!)
  const medLCX = lbX + 364 * s;
  const medLCY = pedLY - 64 * s + Math.sin(p2) * 4 * s;
  roundedRectPath(medLCX - 22 * s, pedLY - 16 * s, 44 * s, 16 * s, 5 * s);
  fillAndStroke(COL.amberDeep, COL.outline, thinStrokeW);
  drawGoldMedallion(medLCX, medLCY, 44 * s, 1.25 * s);

  // =========================================================================
  // 5. CENTER ZONE: GIANT POWER BATTERY HUB
  // Bounding Box: x in [cx - 140*s, cx + 140*s], y in [cy - 285*s, cy + 295*s]
  // Clean battery silhouette without side cable plug or right lightning badge
  // =========================================================================
  const batW = 280 * s;
  const batH = 540 * s;
  const batX = cx - batW * 0.5;
  const batY = cy - 250 * s + Math.sin(p1) * 5 * s;
  const termW = 84 * s;
  const termH = 34 * s;

  // 5A. Battery Top Terminal Nub (y: batY - 34*s)
  roundedRectPath(cx - termW * 0.5, batY - termH, termW, termH + 6 * s, 10 * s);
  fillAndStroke(COL.slateMid, COL.outline, strokeW);
  // Plus sign on terminal nub
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 4.5 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 14 * s, batY - 17 * s);
  ctx.lineTo(cx + 14 * s, batY - 17 * s);
  ctx.moveTo(cx, batY - 30 * s);
  ctx.lineTo(cx, batY - 4 * s);
  ctx.stroke();

  // 5B. Main Battery Shell
  roundedRectPath(batX, batY, batW, batH, 38 * s);
  fillAndStroke(COL.batteryShell, COL.outline, strokeW);

  // Inner Battery Glass Chamber (x: batX + 22*s, y: batY + 24*s, w: batW - 44*s, h: batH - 48*s)
  const chX = batX + 22 * s;
  const chY = batY + 24 * s;
  const chW = batW - 44 * s;
  const chH = batH - 48 * s;

  roundedRectPath(chX, chY, chW, chH, 26 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  // 5C. Clipped Energy Liquid Fill & Wave inside Battery Chamber
  // Liquid height is driven by chargeNorm (0.0 = empty bottom, 1.0 = full top)
  const liqHMax = chH - 24 * s;
  const liqCurrentH = liqHMax * chargeNorm;
  const liqTopY = (chY + chH - 12 * s) - liqCurrentH;

  ctx.save();
  roundedRectPath(chX, chY, chW, chH, 26 * s);
  ctx.clip();

  // Multi-stop Amber-to-Emerald Energy Gradient
  const batGrad = ctx.createLinearGradient(0, chY + chH, 0, chY);
  batGrad.addColorStop(0.00, COL.amberDark);
  batGrad.addColorStop(0.45, COL.amberMid);
  batGrad.addColorStop(0.78, COL.emeraldMid);
  batGrad.addColorStop(1.00, COL.emeraldLight);

  const waveSteps = 24;
  const waveAmp = 6 * s;

  // Back Wave Layer
  ctx.beginPath();
  ctx.moveTo(chX - 10 * s, chY + chH + 20 * s);
  for (let i = 0; i <= waveSteps; i++) {
    const u = i / waveSteps;
    const wx = chX + u * chW;
    const wy = liqTopY - 4 * s + Math.sin(u * Math.PI * 1.5 - p4 + 1.1) * (waveAmp * 0.75);
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(chX + chW + 10 * s, chY + chH + 20 * s);
  ctx.closePath();
  ctx.fillStyle = COL.amberDeep;
  ctx.fill();

  // Front Wave Layer
  ctx.beginPath();
  ctx.moveTo(chX - 10 * s, chY + chH + 20 * s);
  for (let i = 0; i <= waveSteps; i++) {
    const u = i / waveSteps;
    const wx = chX + u * chW;
    const wy = liqTopY + Math.sin(u * Math.PI * 1.5 + p4) * waveAmp;
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(chX + chW + 10 * s, chY + chH + 20 * s);
  ctx.closePath();
  ctx.fillStyle = batGrad;
  ctx.fill();

  // Crisp Meniscus Outline
  ctx.beginPath();
  for (let i = 0; i <= waveSteps; i++) {
    const u = i / waveSteps;
    const wx = chX + u * chW;
    const wy = liqTopY + Math.sin(u * Math.PI * 1.5 + p4) * waveAmp;
    if (i === 0) ctx.moveTo(wx, wy);
    else ctx.lineTo(wx, wy);
  }
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 3.5 * s;
  ctx.stroke();

  // Rising Energy Bubbles inside Battery Liquid (Strictly below liqTopY)
  for (let b = 0; b < 4; b++) {
    const bProg = (sceneProgress * 3 + b * 0.25) % 1;
    const bStartY = chY + chH - 24 * s;
    const bEndY = liqTopY + 22 * s;
    if (bEndY < bStartY) {
      const by = bStartY - bProg * (bStartY - bEndY);
      const bx = cx + (b === 0 ? -42 * s : (b === 1 ? 42 * s : (b % 2 === 0 ? -18 * s : 18 * s))) + Math.sin(p4 + b * 2) * 4 * s;
      const br = (6 + (b % 2) * 2) * s * Math.sin(bProg * Math.PI);
      if (br > 1 * s) {
        ctx.beginPath();
        ctx.arc(bx, by, br, 0, tau);
        fillAndStroke(COL.surfaceWhite, COL.outline, 2.5 * s);
      }
    }
  }

  // Right Vertical Specular Reflection inside Chamber
  roundedRectPath(chX + chW - 18 * s, chY + 28 * s, 8 * s, chH - 56 * s, 4 * s);
  fillAndStroke('rgba(255, 255, 255, 0.65)', null, 0);

  ctx.restore();

  // Re-stroke Inner Chamber Outline
  roundedRectPath(chX, chY, chW, chH, 26 * s);
  fillAndStroke(null, COL.outline, thinStrokeW);

  // 5D. Center Gold Dollar Emblem on Battery Body
  const batMedY = batY + batH * 0.52;
  const batMedScale = 1 + 0.04 * Math.sin(p4);
  drawGoldMedallion(cx, batMedY, 44 * s * batMedScale, 1.35 * s);

  // =========================================================================
  // 6. RIGHT-TOP ZONE: PASSIVE INCOME SURGE & REVENUE METER CARD
  // Bounding Box: x in [cx + 255*s, cx + 685*s], y in [cy - 360*s, cy - 35*s]
  // =========================================================================
  const rtFloatY = Math.cos(p2) * 4.5 * s;
  const rtX = cx + 255 * s;
  const rtY = cy - 360 * s + rtFloatY;
  const rtW = 430 * s;
  const rtH = 315 * s;

  roundedRectPath(rtX, rtY, rtW, rtH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Top Header Strip inside Right-Top Card
  roundedRectPath(rtX + 18 * s, rtY + 18 * s, rtW - 36 * s, 46 * s, 12 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  drawGoldMedallion(rtX + 46 * s, rtY + 41 * s, 16 * s, 0.52 * s);
  roundedRectPath(rtX + 76 * s, rtY + 35 * s, 185 * s, 12 * s, 6 * s);
